esbmc_test_source:
contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // single public test function
    // params: amount to attempt to withdraw
    function run(uint256 amount) public payable {
        // No precondition on amount; we only observe behavior.

        // Read recorded balance for this contract (public getter balances(address) is not present in C,
        // but mapping is private; however specification requires observing only public surface —
        // C does not declare balances as public, so we cannot read it. Instead we use behavior of refund/withdraw
        // observed via address(c).balance changes and whether withdraw reverts. To assert an invariant about
        // the recorded balance we must rely on behavior: after a successful withdraw the contract's balance
        // should decrease by at least amount and withdraw caller cannot increase its recorded balance.
        // We'll first try to withdraw and record whether it reverted and the contract balance delta.

        uint256 beforeContractBal = address(c).balance;
        bool reverted;
        c.withdraw(amount); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }
        uint256 afterContractBal = address(c).balance;

        // General rule: withdraw either reverts leaving contract balance unchanged, or succeeds and
        // decreases contract balance by at least amount (can't create Ether). Additionally, when withdraw succeeds
        // it must not have increased the contract's balance (i.e., afterContractBal <= beforeContractBal).
        // This captures that withdraw cannot add Ether to the contract and that success consumes >= amount.
        assert(
            (reverted && afterContractBal == beforeContractBal)
            ||
            (!reverted && afterContractBal + amount <= beforeContractBal && afterContractBal <= beforeContractBal)
        );
    }

    receive() external payable {}
}

